<?php declare(strict_types=1); function db():PDO{static $pdo;if($pdo instanceof PDO)return $pdo;$h=getenv('QUANTIX_DB_HOST')?:'localhost';$n=getenv('QUANTIX_DB_NAME')?:'';$u=getenv('QUANTIX_DB_USER')?:'';$p=getenv('QUANTIX_DB_PASS')?:'';$pdo=new PDO("mysql:host={$h};dbname={$n};charset=utf8mb4",$u,$p,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);return $pdo;}